import {parseGcode} from './core.js';
export const slicingDefaults=()=>({layer:0.2,firstLayer:0.24,nozzle:0.4,walls:3,topLayers:5,bottomLayers:5,infill:20,pattern:'grid',speed:50,travel:150,temperature:205,bedTemperature:60,retract:0.8,retractSpeed:35,support:false,supportAngle:55,adhesion:'skirt',brim:5,fan:100,tools:1,autoTools:false,baud:115200,advanced:'{}',start:'G21\nG90\nM82\nM140 S{bed}\nM104 S{temperature}\nG28\nM190 S{bed}\nM109 S{temperature}\nG92 E0',end:'M400\nM104 S0\nM140 S0\nM107\nM84',toolChange:'T{tool}'});
const modelSignature=(o,partId)=>JSON.stringify(o.parts.filter(p=>partId==='all'||p.id===partId).map(p=>[p.id,p.fileId,p.demo,p.dims,p.scale,partId==='all'?p.qty:1,o.sliceRotations?.[p.id]||[0,0,0]]));
export function sliceTarget(s,b,o,p,partId='all',copies=1){const config=profileFor(p),parts=o.parts.filter(x=>partId==='all'||x.id===partId);if(!Number.isInteger(copies)||copies<1||copies>100)throw Error('Usa entre 1 y 100 repeticiones.');if(!parts.length)throw Error('Selecciona un componente para laminar.');const materialIds=Array.from({length:config.tools},(_,i)=>config.materials?.[i]||parts.find(x=>(o.toolAssignments?.[x.id]||0)===i)?.matId||'');for(const part of parts){const tool=o.toolAssignments?.[part.id]||0;if(tool>=config.tools||!s.materials.some(m=>!m.retired&&m.id===materialIds[tool]))throw Error('Asigna un filamento disponible a cada herramienta utilizada.');}return {boxId:b.id,objectId:o.id,printerId:p.id,partId,copies,signature:modelSignature(o,partId),diameter:p.diameter,density:p.density,materialIds,partTools:Object.fromEntries(parts.map(x=>[x.id,o.toolAssignments?.[x.id]||0]))};}
export function applySliceEstimates(s,target,text){const o=s.boxes.find(b=>b.id===target.boxId)?.objects.find(o=>o.id===target.objectId);if(!o)return null;if(target.signature&&target.signature!==modelSignature(o,target.partId))throw Error('El modelo cambió durante el laminado. Lamina de nuevo para actualizar la calculadora.');const data=parseGcode(text,target);if(!data.valid)throw Error('El motor terminó sin tiempo y consumo válidos. Revisa el registro antes de cotizar.');const filaments=data.grams.map((grams,i)=>{const matId=target.materialIds[i],m=s.materials.find(m=>m.id===matId);if(grams>0&&!m)throw Error('Ya no está disponible un material del laminado.');const lengthMm=data.lengths[i],diameter=target.diameters?.[i]||target.diameter;return {matId,grams:(lengthMm!=null?lengthMm*Math.PI*(diameter/2)**2/1000*(m?.density||target.density):grams)/target.copies,lengthMm:lengthMm!=null?lengthMm/target.copies:null,diameter};}).filter(f=>f.grams>0);if(!filaments.length)throw Error('El laminado no informa consumo de filamento.');
 const stats={minutes:data.minutes,grams:filaments.reduce((n,f)=>n+f.grams,0)*target.copies,copies:target.copies,partId:target.partId,printerId:target.printerId};
 if(target.partId==='all'){o.gcode={valid:true,source:'CuraEngine local',name:'impresion.gcode',units:target.copies,minutes:data.minutes/target.copies,filaments};for(const part of o.parts){if(Object.hasOwn(target.partTools,part.id)){part.matId=target.materialIds[target.partTools[part.id]];part.grams=null;part.minutes=null;}}}else{const part=o.parts.find(p=>p.id===target.partId);if(!part)return null;part.grams=stats.grams/target.copies;part.minutes=data.minutes/target.copies;part.matId=target.materialIds[target.partTools[part.id]];o.gcode=null;}
 o.lastSliceStats=stats;return stats;
}
export function profileFor(p){p.slicing={...slicingDefaults(),...p.slicing};return p.slicing;}
const num=(n,min,max,label)=>{n=Number(n);if(!Number.isFinite(n)||n<min||n>max)throw Error(`Revisa ${label} (${min}–${max}).`);return n;};
const mapStrings=m=>Object.fromEntries(Object.entries(m).map(([k,v])=>[k,Array.isArray(v)?JSON.stringify(v):String(v)]));
export function engineSettings(p,config){const c={...slicingDefaults(),...config};num(c.layer,.05,1,'altura de capa');num(c.nozzle,.1,2,'boquilla');if(c.layer>c.nozzle*.8)throw Error('La capa supera el 80% del diámetro de boquilla.');for(const k of ['walls','topLayers','bottomLayers','tools']){num(c[k],k==='tools'?1:0,k==='tools'?8:100,k);if(!Number.isInteger(+c[k]))throw Error('Las capas y herramientas deben ser enteras.');}num(c.temperature,0,350,'temperatura');num(c.bedTemperature,0,150,'cama');num(c.speed,1,500,'velocidad');num(c.infill,0,100,'relleno');num(c.retract,0,30,'retracción');
 if(c.tools>1&&!c.autoTools)throw Error('Confirma que el equipo admite varias herramientas antes de laminar con ellas.');
 const template=t=>t.replaceAll('{temperature}',String(c.temperature)).replaceAll('{bed}',String(c.bedTemperature));
 const global={machine_name:p.printer,machine_width:p.bedX,machine_depth:p.bedY,machine_height:p.bedZ,machine_center_is_zero:false,machine_extruder_count:c.tools,machine_gcode_flavor:'RepRap (Marlin/Sprinter)',machine_heated_bed:true,machine_start_gcode:template(c.start),machine_end_gcode:template(c.end),material_bed_temperature:c.bedTemperature,material_bed_temperature_layer_0:c.bedTemperature,layer_height:c.layer,layer_height_0:c.firstLayer,wall_line_count:c.walls,wall_thickness:c.nozzle*c.walls,top_layers:c.topLayers,bottom_layers:c.bottomLayers,top_thickness:c.layer*c.topLayers,bottom_thickness:c.layer*c.bottomLayers,top_bottom_thickness:Math.max(c.topLayers,c.bottomLayers)*c.layer,infill_sparse_density:c.infill,infill_pattern:c.pattern,infill_line_distance:c.infill?c.nozzle*100/c.infill*(['grid','triangles','cubic'].includes(c.pattern)?(c.pattern==='triangles'?3:2):1):0,infill_sparse_thickness:c.layer,support_enable:c.support,support_angle:c.supportAngle,support_type:'buildplate',adhesion_type:c.adhesion,brim_width:c.brim,brim_line_count:Math.ceil(c.brim/c.nozzle),skirt_line_count:2,speed_print:c.speed,speed_infill:c.speed,speed_wall:c.speed*.6,speed_wall_0:c.speed*.5,speed_wall_x:c.speed*.7,speed_topbottom:c.speed*.6,speed_travel:c.travel,speed_layer_0:Math.min(c.speed,25),speed_print_layer_0:Math.min(c.speed,25),speed_travel_layer_0:Math.min(c.travel,80),retraction_enable:c.retract>0,retraction_amount:c.retract,retraction_speed:c.retractSpeed,retraction_retract_speed:c.retractSpeed,retraction_prime_speed:c.retractSpeed,cool_fan_enabled:c.fan>0,cool_fan_speed:c.fan,cool_fan_speed_min:c.fan,cool_fan_speed_max:c.fan,cool_fan_speed_0:0,material_print_temperature:c.temperature,material_print_temperature_layer_0:c.temperature,material_initial_print_temperature:c.temperature,material_final_print_temperature:c.temperature,material_standby_temperature:Math.max(0,c.temperature-30),material_diameter:p.diameter,material_flow:100,machine_nozzle_size:c.nozzle,line_width:c.nozzle,wall_line_width:c.nozzle,wall_line_width_0:c.nozzle,wall_line_width_x:c.nozzle,skin_line_width:c.nozzle,infill_line_width:c.nozzle,support_line_width:c.nozzle,support_interface_line_width:c.nozzle,skirt_brim_line_width:c.nozzle,prime_tower_line_width:c.nozzle,center_object:false,mesh_position_x:0,mesh_position_y:0,mesh_position_z:0};
 let advanced;try{advanced=JSON.parse(c.advanced||'{}');}catch{throw Error('Los ajustes avanzados deben ser JSON válido.');}if(!advanced||typeof advanced!=='object'||Array.isArray(advanced))throw Error('Formato avanzado inválido.');const extra=advanced.global||advanced;for(const [k,v] of Object.entries(extra)){if(k==='extruders')continue;if(v!==null&&(typeof v!=='object'||Array.isArray(v)))global[k]=v;else throw Error('Los valores avanzados deben estar resueltos, sin expresiones.');}
 const extruders=Array.from({length:c.tools},(_,i)=>({...global,extruder_nr:i,machine_extruder_cooling_fan_number:i,machine_nozzle_offset_x:0,machine_nozzle_offset_y:0,extruder_start_code:'',extruder_end_code:'',...(advanced.extruders?.[i]||{})}));return {settings:mapStrings(global),extruders:extruders.map(mapStrings)};
}
export function parseToolpaths(text,limit=180000){const lines=text.split(/\r?\n/),paths=[],layers=[],warnings=new Set();let x=0,y=0,z=0,e=0,f=1800,unit=1,abs=true,absE=true,tool=0,layer=0,moves=0;const stride=Math.max(1,Math.ceil(lines.length/limit));
 for(let i=0;i<lines.length;i++){const raw=lines[i];const lm=raw.match(/^;LAYER:(\d+)/);if(lm||/^;\s*LAYER_CHANGE/.test(raw)){layer=lm?+lm[1]+1:layer+1;layers.push({layer,index:i,x,y,z,e,f,unit,abs,absE,tool});}const cmd=raw.replace(/;.*$/,'').trim().toUpperCase(),op=cmd.match(/^(?:N\d+\s*)?([GMT]\d+)/)?.[1];if(!op)continue;const args=Object.fromEntries([...cmd.matchAll(/([XYZEFIJKR])\s*(-?(?:\d+\.?\d*|\.\d+))/g)].map(m=>[m[1],+m[2]]));if(op[0]==='T'){tool=+op.slice(1);continue;}if(op==='G20'){unit=25.4;continue;}if(op==='G21'){unit=1;continue;}if(op==='G90'){abs=true;absE=true;continue;}if(op==='G91'){abs=false;absE=false;continue;}if(op==='M82'){absE=true;continue;}if(op==='M83'){absE=false;continue;}if(op==='G92'){if(args.X!=null)x=args.X*unit;if(args.Y!=null)y=args.Y*unit;if(args.Z!=null)z=args.Z*unit;if(args.E!=null)e=args.E*unit;continue;}
 if(!['G0','G1','G2','G3'].includes(op))continue;const nx=args.X==null?x:args.X*unit+(abs?0:x),ny=args.Y==null?y:args.Y*unit+(abs?0:y),nz=args.Z==null?z:args.Z*unit+(abs?0:z),ne=args.E==null?e:args.E*unit+(absE?0:e);if(args.F!=null)f=args.F*unit;const extrude=ne>e+1e-5;
 if(op==='G2'||op==='G3')warnings.add('Hay arcos G2/G3: la vista dibuja sus extremos como segmentos; revisa los arcos en el laminador original.');
 if((x!==nx||y!==ny||z!==nz)&&moves++%stride===0)paths.push({from:[x,y,z],to:[nx,ny,nz],layer,tool,extrude});x=nx;y=ny;z=nz;e=ne;
 }
 if(stride>1)warnings.add('Vista aligerada: se muestra una muestra de los movimientos del archivo.');return {paths,layers,warnings:[...warnings],maxLayer:layers.reduce((n,l)=>Math.max(n,l.layer),1),lines:lines.length};
}
export function colorChanges(text,changes,p){const config=profileFor(p),analysis=parseToolpaths(text,100),inserts=new Map(),seen=new Set();for(const c of changes){const layer=Number(c.layer);if(seen.has(layer))throw Error('Solo puede haber un cambio programado por capa.');seen.add(layer);const l=analysis.layers.find(l=>l.layer===layer);if(!l)throw Error('No existe la capa '+layer);let code;
 if(c.mode==='tool'){if(!config.autoTools||!Number.isInteger(+c.tool)||c.tool<0||c.tool>=config.tools)throw Error('Configura las herramientas automáticas de esta impresora.');code=config.toolChange.replaceAll('{tool}',String(c.tool));}
 else if(c.mode==='M600'||c.mode==='M0')code=c.mode;
 else if(c.mode==='host'){if(!l.abs||l.unit!==1||l.layer<2||l.z+3>p.bedZ)throw Error('La pausa USB necesita coordenadas absolutas en mm, a partir de la capa 2 y al menos 3 mm libres en Z.');const n=v=>Number(v.toFixed(5));code=`M400\nM83\nG1 E-2 F1800\nG90\nG1 Z${n(l.z+3)} F600\nG1 X5 Y5 F3000\n;WOODS_HOST_PAUSE\nG90\nM83\nG1 E2 F1800\nG1 X${n(l.x)} Y${n(l.y)} F3000\nG1 Z${n(l.z)} F600\nG92 E${n(l.e)}\n${l.absE?'M82':'M83'}\nG1 F${n(l.f)}`;}
 else throw Error('Modo de cambio desconocido.');inserts.set(l.index,`;WOODS_COLOR_CHANGE: capa ${layer}\n${code}\n`);
 }
 return text.split(/\r?\n/).map((line,i)=>(inserts.get(i)||'')+line).join('\n');
}
